import pandas as pd

def clean(df):
    df = df.copy()
    # Standardise Category label variant
    if 'Category' in df.columns:
        df['Category'] = df['Category'].astype(str).str.strip()
        df['Category'] = df['Category'].replace({'office supplies': 'Office Supplies'})
    # Remove exact duplicate rows
    df = df.drop_duplicates()
    # Enforce unique Order_ID
    if 'Order_ID' in df.columns:
        df = df.drop_duplicates(subset=['Order_ID'], keep='first')
    # Optional Region typo fixes – not required for the question but harmless
    if 'Region' in df.columns:
        df['Region'] = df['Region'].replace({'Suoth': 'South', 'Eats': 'East'})
    return df

def answer(df):
    if 'Category' not in df.columns or 'Order_ID' not in df.columns:
        return {}
    sub = df.dropna(subset=['Category'])
    # Count unique orders per category
    counts = sub.groupby('Category')['Order_ID'].nunique()
    return {str(k): int(v) for k, v in counts.items()}
